// Crypto___Security_Engine_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module Crypto___Security_Engine_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [127:0] c_msg,
  input logic [127:0] c_key,
  input logic [6:0] c_msg_len,
  input logic  c_mode,
  input logic [1:0] c_msg_widx,
  input logic [1:0] c_key_widx,
  input logic  c_msg_we,
  input logic  c_key_we,
  input logic  c_start,
  input logic [255:0] c_digest,
  input logic  c_busy,
  input logic  c_done,
  input logic  c_irq
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 24;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:23];          // model of every stored word
  logic [1:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_done) m_set[0] = 1'b1;
    if (c_irq) m_set[1] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_w[23] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h3;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 12) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 13) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'hFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 14) ? PWDATA & m_be & 32'h7 : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h53480200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return 0;
      15: return (32'(c_digest[31:0]) << 0);
      16: return (32'(c_digest[63:32]) << 0);
      17: return (32'(c_digest[95:64]) << 0);
      18: return (32'(c_digest[127:96]) << 0);
      19: return (32'(c_digest[159:128]) << 0);
      20: return (32'(c_digest[191:160]) << 0);
      21: return (32'(c_digest[223:192]) << 0);
      22: return (32'(c_digest[255:224]) << 0);
      23: return (32'(c_busy) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][1:0] & m_w[2][1:0]))
  `SVA_INV(a_core_msg_31_0, c_msg[31:0] == m_w[5][31:0])
  `SVA_INV(a_core_msg_63_32, c_msg[63:32] == m_w[6][31:0])
  `SVA_INV(a_core_msg_95_64, c_msg[95:64] == m_w[7][31:0])
  `SVA_INV(a_core_msg_127_96, c_msg[127:96] == m_w[8][31:0])
  `SVA_INV(a_core_key_31_0, c_key[31:0] == m_w[9][31:0])
  `SVA_INV(a_core_key_63_32, c_key[63:32] == m_w[10][31:0])
  `SVA_INV(a_core_key_95_64, c_key[95:64] == m_w[11][31:0])
  `SVA_INV(a_core_key_127_96, c_key[127:96] == m_w[12][31:0])
  `SVA_INV(a_core_msg_len, c_msg_len == m_w[13][6:0])
  `SVA_INV(a_core_mode, c_mode == m_w[13][7:7])
  `SVA_INV(a_core_msg_widx, c_msg_widx == m_w[13][9:8])
  `SVA_INV(a_core_key_widx, c_key_widx == m_w[13][11:10])
  `SVA_INV(a_core_msg_we, c_msg_we == m_pulse_CMD[0])
  `SVA_INV(a_core_key_we, c_key_we == m_pulse_CMD[1])
  `SVA_INV(a_core_start, c_start == m_pulse_CMD[2])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_msg[31:0] == 32'h0 && c_msg[63:32] == 32'h0 && c_msg[95:64] == 32'h0 && c_msg[127:96] == 32'h0 && c_key[31:0] == 32'h0 && c_key[63:32] == 32'h0 && c_key[95:64] == 32'h0 && c_key[127:96] == 32'h0 && c_msg_len == 7'h0 && c_mode == 1'h0 && c_msg_widx == 2'h0 && c_key_widx == 2'h0 && c_msg_we == 1'h0 && c_key_we == 1'h0 && c_start == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_MSG0, m_rd && m_map && m_idx == 5)
  `FC(wr_MSG0, m_wr && m_map && m_idx == 5)
  `FC(rd_MSG1, m_rd && m_map && m_idx == 6)
  `FC(wr_MSG1, m_wr && m_map && m_idx == 6)
  `FC(rd_MSG2, m_rd && m_map && m_idx == 7)
  `FC(wr_MSG2, m_wr && m_map && m_idx == 7)
  `FC(rd_MSG3, m_rd && m_map && m_idx == 8)
  `FC(wr_MSG3, m_wr && m_map && m_idx == 8)
  `FC(rd_KEY0, m_rd && m_map && m_idx == 9)
  `FC(wr_KEY0, m_wr && m_map && m_idx == 9)
  `FC(rd_KEY1, m_rd && m_map && m_idx == 10)
  `FC(wr_KEY1, m_wr && m_map && m_idx == 10)
  `FC(rd_KEY2, m_rd && m_map && m_idx == 11)
  `FC(wr_KEY2, m_wr && m_map && m_idx == 11)
  `FC(rd_KEY3, m_rd && m_map && m_idx == 12)
  `FC(wr_KEY3, m_wr && m_map && m_idx == 12)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 13)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 13)
  `FC(rd_CMD, m_rd && m_map && m_idx == 14)
  `FC(wr_CMD, m_wr && m_map && m_idx == 14)
  `FC(rd_DIGEST0, m_rd && m_map && m_idx == 15)
  `FC(wr_DIGEST0, m_wr && m_map && m_idx == 15)
  `FC(rd_DIGEST1, m_rd && m_map && m_idx == 16)
  `FC(wr_DIGEST1, m_wr && m_map && m_idx == 16)
  `FC(rd_DIGEST2, m_rd && m_map && m_idx == 17)
  `FC(wr_DIGEST2, m_wr && m_map && m_idx == 17)
  `FC(rd_DIGEST3, m_rd && m_map && m_idx == 18)
  `FC(wr_DIGEST3, m_wr && m_map && m_idx == 18)
  `FC(rd_DIGEST4, m_rd && m_map && m_idx == 19)
  `FC(wr_DIGEST4, m_wr && m_map && m_idx == 19)
  `FC(rd_DIGEST5, m_rd && m_map && m_idx == 20)
  `FC(wr_DIGEST5, m_wr && m_map && m_idx == 20)
  `FC(rd_DIGEST6, m_rd && m_map && m_idx == 21)
  `FC(wr_DIGEST6, m_wr && m_map && m_idx == 21)
  `FC(rd_DIGEST7, m_rd && m_map && m_idx == 22)
  `FC(wr_DIGEST7, m_wr && m_map && m_idx == 22)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 23)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 23)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_DONE_set, m_set[0])
  `FC(irq_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_PROTOCOL_set, m_set[1])
  `FC(irq_PROTOCOL_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_PROTOCOL_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_PROTOCOL_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(cmd_msg_we, m_pulse_CMD[0])
  `FC(cmd_key_we, m_pulse_CMD[1])
  `FC(cmd_start, m_pulse_CMD[2])
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

